#ifdef NDEBUG
#undef NDEBUG
#endif
#include "semantic_result.h"
#include <assert.h>
#include <stdio.h>
static void scope_growth(void){SemanticResult r;uint32_t id=0u,i;assert(semantic_result_init(&r)==SEMANTIC_RESULT_OK);for(i=0;i<7u;++i)assert(semantic_result_add_scope(&r,1u,1u,0u,i+2u,&id)==SEMANTIC_RESULT_OK);semantic_result_test_fail_allocation_at(&r,1u);assert(semantic_result_add_scope(&r,1u,1u,0u,20u,&id)==SEMANTIC_RESULT_OUT_OF_MEMORY);assert(semantic_result_test_get_allocation_attempts(&r)==1u);semantic_result_destroy(&r);}
static void type_allocations(void){SemanticResult r;uint32_t id=99u;assert(semantic_result_init(&r)==SEMANTIC_RESULT_OK);semantic_result_test_fail_allocation_at(&r,1u);assert(semantic_result_intern_type(&r,SEMANTIC_RESULT_TYPE_PRIMITIVE,0u,"i32",0u,0u,&id)==SEMANTIC_RESULT_OUT_OF_MEMORY);assert(id==99u&&r.type_count==0u&&r.types==NULL);semantic_result_test_fail_allocation_at(&r,2u);assert(semantic_result_intern_type(&r,SEMANTIC_RESULT_TYPE_PRIMITIVE,0u,"i32",0u,0u,&id)==SEMANTIC_RESULT_OUT_OF_MEMORY);assert(r.type_count==0u&&r.types==NULL&&semantic_result_test_get_allocation_attempts(&r)==2u);semantic_result_destroy(&r);}
static void symbol_allocations(void){SemanticResult r;uint32_t id=0u;assert(semantic_result_init(&r)==SEMANTIC_RESULT_OK);semantic_result_test_fail_allocation_at(&r,1u);assert(semantic_result_add_symbol(&r,1u,2u,SEMANTIC_RESULT_SYMBOL_VARIABLE,0u,"value",0u,&id)==SEMANTIC_RESULT_OUT_OF_MEMORY);assert(r.symbol_count==0u&&r.symbols==NULL);semantic_result_test_fail_allocation_at(&r,2u);assert(semantic_result_add_symbol(&r,1u,2u,SEMANTIC_RESULT_SYMBOL_VARIABLE,0u,"value",0u,&id)==SEMANTIC_RESULT_OUT_OF_MEMORY);assert(r.symbol_count==0u&&r.symbols==NULL&&semantic_result_test_get_allocation_attempts(&r)==2u);semantic_result_destroy(&r);}
static void annotation_conversion_allocations(void){SemanticResult r;uint32_t type=0u;assert(semantic_result_init(&r)==SEMANTIC_RESULT_OK);assert(semantic_result_intern_type(&r,SEMANTIC_RESULT_TYPE_PRIMITIVE,0u,NULL,0u,0u,&type)==SEMANTIC_RESULT_OK);semantic_result_test_fail_allocation_at(&r,1u);assert(semantic_result_set_annotation(&r,2u,1u,0u,type,SEMANTIC_RESULT_VALUE_RVALUE,0u)==SEMANTIC_RESULT_OUT_OF_MEMORY);assert(r.annotation_count==0u&&r.annotations==NULL);semantic_result_test_fail_allocation_at(&r,1u);assert(semantic_result_add_conversion(&r,2u,0u,type,type,SEMANTIC_RESULT_CONVERSION_IDENTITY,SEMANTIC_RESULT_CONVERSION_FLAG_IMPLICIT)==SEMANTIC_RESULT_OUT_OF_MEMORY);assert(r.conversion_count==0u&&r.conversions==NULL);semantic_result_destroy(&r);}
static void relation_allocations(void){SemanticResult r;uint32_t owner=0u;assert(semantic_result_init(&r)==SEMANTIC_RESULT_OK);assert(semantic_result_add_symbol(&r,1u,2u,SEMANTIC_RESULT_SYMBOL_FUNCTION,0u,"f",0u,&owner)==SEMANTIC_RESULT_OK);semantic_result_test_fail_allocation_at(&r,1u);assert(semantic_result_add_relation(&r,owner,SEMANTIC_RESULT_RELATION_FUNCTION_PARAMETER,0u,0u,3u,"arg",0u)==SEMANTIC_RESULT_OUT_OF_MEMORY);assert(r.relation_count==0u&&r.relations==NULL);semantic_result_test_fail_allocation_at(&r,2u);assert(semantic_result_add_relation(&r,owner,SEMANTIC_RESULT_RELATION_FUNCTION_PARAMETER,0u,0u,3u,"arg",0u)==SEMANTIC_RESULT_OUT_OF_MEMORY);assert(r.relation_count==0u&&r.relations==NULL&&semantic_result_test_get_allocation_attempts(&r)==2u);semantic_result_destroy(&r);}
static void finalize_workspace(void){SemanticResult r;uint32_t scope=0u;assert(semantic_result_init(&r)==SEMANTIC_RESULT_OK);assert(semantic_result_add_scope(&r,1u,1u,0u,2u,&scope)==SEMANTIC_RESULT_OK);semantic_result_test_fail_allocation_at(&r,1u);assert(semantic_result_finalize(&r,2u)==SEMANTIC_RESULT_OUT_OF_MEMORY);assert(r.finalized==0u&&semantic_result_test_get_allocation_attempts(&r)==1u);semantic_result_destroy(&r);}
int main(void){scope_growth();type_allocations();symbol_allocations();annotation_conversion_allocations();relation_allocations();finalize_workspace();puts("Persistent semantic result allocation failure tests passed.");return 0;}